helper.pro.quickRepair.html = String.raw`<html charset="UTF-8">

<head>

<style>

    html{overflow:hidden;}

    body{line-height:30px; font-size:13px; font-family:"Helvetica","Lucida Console","Microsoft soft"; user-select:none;}

    h3{display:block; margin-top:12px; margin-bottom:8px; text-align:center; width:100%}

    label,span{display:inline-block; height:13px; line-height:13px;} i{margin-left:8px;}

    input[type=checkbox]{margin-left:2px; margin-right:1px; margin-top:8px; vertical-align:top; width:13px; height:13px; accent-color:gray;}

    select{color:#333; border:1px solid #999; border-radius:3px; outline-style:none; margin-left:0px; padding-top:0px; width:65px; height:20px; font-size:13px;} 

    button{border:1px solid #999; border-radius:3px; outline-style:none; text-align:center; margin-top:0px; width:80px; height:22px;}

    button:hover{background-color:#ccc;} button:focus{background-color:#ccc;} button:active{transform: translateY(1px);}

    

    .panel{border:1px solid silver; border-radius:6px; margin:4px; padding:4px; padding-left:8px; box-shadow: 3px 3px 6px gray;}

    .foot{display:flex; margin-top:12px; padding-bottom:2px; align-items:center; width:100%;} 

    .combo-box{display:inline-block; position:relative; width:65px; height:20px;} .combo-list{width:100%;}

    .combo-edit{position:absolute; height:13px; width:45px; left:2px; top:7px; outline-style:none; border:0px; padding-left:2px; background-color:transparent; font-size:13px;}



    #state{margin-left:4px; width:45px; text-align:center;} #action{margin:auto;} #dummy{margin-right:4px; width:45px}

</style>

<script>

    function $(a) {

        return a && '#'==a[0] && document.getElementById(a.substring(1));

    }



    function apply() {

        var setting = {army:{}, option:{}, speed:{}};

        setting.army.land = $("#army_l").checked;

        setting.army.sea = $("#army_h").checked;

        setting.army.air = $("#army_k").checked;

        setting.army.common = $("#army_n").checked;

        setting.army.thor = $("#army_t").checked;

        setting.option.hospital = $("#opt_1").checked;

        setting.option.injured = $("#opt_2").checked;

        setting.option.speed = $("#opt_3").checked;

        setting.option.all = $("#opt_4").checked;

        setting.option.merge = $("#opt_5").checked;

        setting.speed.item = $("#opt_6").checked;

        setting.speed.gold = $("#opt_7").checked;

        parent.helper.pro.quickRepair.apply(setting);

    }



    function render(setting, state) {

        $("#army_l").checked = setting.army.land;

        $("#army_h").checked = setting.army.sea;

        $("#army_k").checked = setting.army.air;

        $("#army_n").checked = setting.army.common;

        $("#army_t").checked = setting.army.thor;



        $("#opt_1").checked = setting.option.hospital;

        $("#opt_2").checked = setting.option.injured;

        $("#opt_3").checked = setting.option.speed;

        $("#opt_4").checked = setting.option.all;

        $("#opt_5").checked = setting.option.merge;

        $("#opt_6").checked = setting.speed.item;

        $("#opt_7").checked = setting.speed.gold;



        $("#exopt1").style.display = setting.option.hospital ? "inline-block" : "none";

        $("#exopt2").style.display = setting.option.injured ? "inline-block" : "none";

        $("#speed").style.visibility = setting.option.speed ? "visible" : "hidden";



        $("#state").innerText = state.running ? "运行中" : "未运行";

        $("#state").style.backgroundColor = state.running ? "greenyellow" : "#aaa";

        $("#state").style.borderRadius = "2px";



        $("#action").innerText = state.running ? "停止" : "启动";

    }



    function action() {

        var o = parent.helper.pro.quickRepair;

        o.state.running ? o.suspend() : o.startup();

    }

</script>

</head>

<body>

    <h3>自动修理士兵</h3>

    <div class="panel">

        <span>修理兵种:</span>

        <i></i>

        <input type="checkbox" id="army_l" onclick="apply()"><span>陆军</span>

        <i></i>

        <input type="checkbox" id="army_h" onclick="apply()"><span>海军</span>

        <i></i>

        <input type="checkbox" id="army_k" onclick="apply()"><span>空军</span>

        <i></i>

        <input type="checkbox" id="army_n" onclick="apply()"><span>普通</span>

        <i></i>

        <input type="checkbox" id="army_t" onclick="apply()"><span>雷神</span>

        <br>

        <span>修理选项:</span>

        <i></i>

        <input type="checkbox" id="opt_1" onclick="apply()"><span>受伤</span>

        <i></i>

        <input type="checkbox" id="opt_2" onclick="apply()"><span>损毁</span>

        <i></i>

        <div id="exopt1">

            <input type="checkbox" id="opt_3" onclick="apply()"><span>加速</span>

            <i></i>

            <input type="checkbox" id="opt_4" onclick="apply()"><span>全部</span>

        </div>

        <i></i>

        <div id="exopt2">

            <input type="checkbox" id="opt_5" onclick="apply()"><span>合兵</span>

        </div>

        <br>

        <div id="speed">

            <span>加速方式:</span>

            <i></i>

            <input type="checkbox" id="opt_6" onclick="apply()"><span>道具</span>

            <i></i>

            <input type="checkbox" id="opt_7" onclick="apply()"><span>钻石</span>

        </div>

    </div>

    <div class="foot">

        <span id="state">未运行</span>

        <button id="action" onclick="action()">启动</button>

        <span id="dummy"></span>

    </div>

</body>

</html>`;
