        useItem.checked = setting.useItem;

        useGold.checked = setting.useGold;



        var n = parent.__require("ProfessionController").default.Instance.MyProfessionData?.id;

        profession_desc.innerText = 72001 == n ? '战斗精英' : 72002 == n ? '机械大师' : '进阶天赋';

